import XCTest
@testable import ManagerCore

final class GeneratedThumbnailPNGTests: XCTestCase {
    func testGeneratedExifIsRemovedAndPixelChunksRemainIdentical() throws {
        let clean = try XCTUnwrap(Data(base64Encoded: ""))
        let withExif = try XCTUnwrap(Data(base64Encoded: ""))
        XCTAssertEqual(try GeneratedThumbnailPNG.canonical(withExif), clean)
        XCTAssertEqual(try GeneratedThumbnailPNG.canonical(clean), clean)
        var duplicate = withExif
        duplicate.insert(contentsOf: withExif[46..<66], at: 66)
        XCTAssertThrowsError(try GeneratedThumbnailPNG.canonical(duplicate))
    }
    func testMalformedOrAppearanceChangingChunksAreRejected() throws {
        let clean = try XCTUnwrap(Data(base64Encoded: ""))
        let transparency = try XCTUnwrap(Data(base64Encoded: ""))
        XCTAssertThrowsError(try GeneratedThumbnailPNG.canonical(transparency))
        XCTAssertThrowsError(try GeneratedThumbnailPNG.canonical(clean.dropLast()))
        var corrupt = clean; corrupt[29] ^= 1
        XCTAssertThrowsError(try GeneratedThumbnailPNG.canonical(corrupt))
        var trailing = clean; trailing.append(0)
        XCTAssertThrowsError(try GeneratedThumbnailPNG.canonical(trailing))
    }
}
